"""Build static review HTML from remotely produced results; no image processing."""
from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[3];out=root/'runs/hemp-sam3-tiles-v1';r=json.loads((out/'results/report.json').read_text())
rows=[]
for x in r['results']:
 a=x.get('complete_audit',{});metric='Not labeled' if not a else f"{a['one_to_one_matches_iou05']}/{a['visible_whole_leaves_ge16px']} · precision {a['precision']:.0%} · recall {a['recall']:.0%}"
 rows.append(f"<tr><td>{x['image']}</td><td>{x['grid']}×{x['grid']}</td><td>{x['threshold']}</td><td>{x['raw']}</td><td>{x['edge_fragments']}</td><td>{x['deduplicated_complete']}</td><td>{metric}</td></tr>")
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SAM3 · overlapping crops</title><style>body{font:17px system-ui;background:#eff1e8;color:#20382b;margin:0;padding:28px;max-width:1500px;margin:auto}h1{font-size:40px;margin-bottom:12px}p{max-width:1000px;line-height:1.55}.controls{display:flex;gap:14px;flex-wrap:wrap;padding:16px 0;position:sticky;top:0;background:#eff1e8}select{font:inherit;padding:8px;border:1px solid #a9b8aa;border-radius:8px}section{background:white;border-radius:14px;padding:18px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.grid img{width:100%;display:block;background:#10170f}.caption{padding:10px;font-size:14px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px;border-bottom:1px solid #d3ded1;text-align:left}.warn{background:#fff2d5;padding:16px;border-radius:12px}a{color:#216b56}.wide{overflow:auto}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}} </style>
<h1>Does SAM3 improve when we zoom in?</h1><p>The same frozen pixels, evaluated as a full image or overlapping 2×2 and 3×3 crops. Each crop is mapped back into the original image; duplicate masks are suppressed. Click an image to inspect its original pixels.</p><p class="warn"><b>These colors show predictions, not verified anatomy.</b> Real-photo leaf counts are unknown. Synthetic precision and recall use exact visible whole-leaf IDs. Cropping cannot recover missing detail. The 0.1 setting is a diagnostic, not a replacement acceptance threshold.</p>
<div class="controls"><label>Confidence <select id="confidence"><option value="standard">0.5 · primary</option><option value="low-confidence">0.1 · diagnostic</option></select></label><label>Crop-edge handling <select id="edge"><option value="complete">Exclude uncertain edge fragments</option><option value="all">Show all masks after deduplication</option></select></label></div>
'''
for name in ['reference','broad-render','narrow-render']:
 page+=f'<section><h2>{html.escape(name)}</h2><div class="grid"><div><div class="caption">Original input</div><a href="results/{name}/input.png"><img src="results/{name}/input.png"></a></div>'
 for n in [1,2,3]:page+=f'<div><div class="caption">{n}×{n} · {n*n} image(s)</div><a class="prediction-link" data-base="results/{name}/grid-{n}/"><img class="prediction" data-base="results/{name}/grid-{n}/"></a><a href="results/{name}/grid-{n}/tile-layout.png">Tile boundaries</a></div>'
 page+='</div></section>'
page+='<section><h2>Measured comparison</h2><p>Counts refer to proposals. Complete-mask metrics exclude predictions touching internal crop edges. Matching is one-to-one at IoU ≥ 0.5, restricted to whole leaves with at least 16 visible pixels.</p><div class="wide"><table><thead><tr><th>Image</th><th>Grid</th><th>Threshold</th><th>Raw masks</th><th>Edge fragments</th><th>Complete masks</th><th>Synthetic matches</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section>'
page+='''<p><a href="results/report.json">Raw report</a> · <a href="../hemp-sam3-comparison-v1/index.html">Previous comparison</a></p><script>function refresh(){const suffix=confidence.value+'-'+edge.value+'.png';document.querySelectorAll('.prediction').forEach(x=>x.src=x.dataset.base+suffix);document.querySelectorAll('.prediction-link').forEach(x=>x.href=x.dataset.base+suffix)}confidence.onchange=edge.onchange=refresh;refresh();</script>'''
(out/'index.html').write_text(page);print(out/'index.html')
